cd /workspace && python3 - <<'EOF'
import hashlib
def W(seed,r,t,a,b):
    d = ("%d:%d:%d:%d:%d"%(seed,r,t,a,b)).encode()
    return int.from_bytes(hashlib.sha256(d).digest()[:8],'big')
seed=7
flows = [(-1,0),(-1,1),(0,-1),(0,1),(1,-1),(1,0)]
pools = {(0,1):[8,9], (1,0):[3,4], (-1,0):[5], (0,-1):[6], (-1,1):[7], (1,-1):[2]}
for r in (0,1):
    for f in flows:
        if r in f:
            a,b=f
            n=len(pools[f])
            idxs=[W(seed,r,t,a,b)%n for t in (0,1)]
            vals=[pools[f][i] for i in idxs]
            print("router",r,"flow",f,"idx",idxs,"samples",vals)
EOF
